-- ============================================================================
-- PARTIE 19 — Contenu du module 7 « Inclusion et repérage » (3 séquences)
-- Source : Projet pédagogique Koalakids (accueil de toutes les familles, enfant
-- unique, styles d'attachement, lutte contre les stéréotypes, inclusion).
-- Le projet pédagogique ne traite pas du repérage de difficultés de développement :
-- ce volet n'est pas couvert par ce module.
-- Script reconstitué à partir de la base (contenu publié).
-- Relançable : la trame est remplacée, les blocs ne sont ajoutés qu'une fois.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 19.1a Trame de la séquence 1/3 (Apport). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Chaque enfant est unique : l'accueillir sans condition, c'est adapter notre accompagnement à lui.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire en quoi accueillir chaque enfant et chaque famille sans condition suppose d'adapter son accompagnement, et de repérer les stéréotypes qui peuvent s'y glisser.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Inclusion et égalité des chances"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Présenter les 3 séances du module : apport, analyse d'une situation vécue, test d'une pratique.", "Chacun pense à ce qui rend un enfant du site unique, sans le nommer."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Chaque enfant est unique : on l'accueille sans condition et on adapte notre accompagnement à lui.", "idees": ["La crèche accueille toutes les familles, quels que soient leur composition, leur culture, leur situation sociale, leur situation de santé, leur mode de vie ou leurs choix éducatifs. Premier principe de la charte nationale : l'acceptation inconditionnelle de l'enfant et de ses parents.", "Chaque enfant est unique et différent des autres : on le respecte et on l'encourage dans sa singularité. Tous ne développent pas le même style d'attachement : certains s'appuient sur leurs parents et partent à l'aventure, d'autres ont besoin d'un ou plusieurs professionnels, d'autres encore d'une présence continue. On fait preuve d'adaptabilité et de disponibilité.", "On lutte contre toute forme de discrimination et de catégorisation : aucun stéréotype lié au sexe de l'enfant, à son âge, à sa situation ou à celle de ses parents. On soutient son identité et son individualité."], "support": "Projet pédagogique Koalakids, « Respecter et accompagner chaque enfant avec confiance et enthousiasme dans l'expression de son plein potentiel d'être humain »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir un enfant ou une famille du site, sans les nommer, et décrire ce qui les rend uniques. On analyse ce que fait l'adulte, pas ce qu'est l'enfant.", "questions": ["Qu'est-ce qui rend cet enfant (ou cette famille) unique ?", "De quoi a-t-il besoin pour se sentir accueilli tel qu'il est ?", "Mon accompagnement s'adapte-t-il à lui, ou l'ai-je attendu comme les autres ?", "Que faire autrement ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : observer comment un enfant s'appuie sur les adultes avant de proposer mon accompagnement.", "Exemple : repérer une phrase qui renvoie un enfant à son sexe ou à son âge, et la reformuler.", "Exemple : accueillir une famille en prenant le temps de l'écouter, sans protocole."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 2/3 : analyse d'une situation où un enfant ou une famille sort de nos habitudes."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 7 % 1/3 %';
-- FIN 19.1a

-- ---------------------------------------------------------------------------
-- 19.1b Blocs de la séquence 1/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Accueillir sans condition", "paragraphes": ["Chaque enfant est unique et différent des autres. Il est considéré d'emblée comme **une personne à part entière**, qu'il est essentiel de respecter et d'encourager dans sa singularité.", "Cette première séance pose un repère : on accueille l'enfant et sa famille **quelle que soit leur situation**, et c'est à nous d'adapter notre accompagnement, pas à l'enfant de se couler dans un modèle."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Toutes les familles sont accueillies,** quels que soient leur composition, leur culture, leur situation sociale ou de santé, leurs choix éducatifs.", "**Chaque enfant est unique :** tous ne s'attachent pas de la même façon. On adapte notre disponibilité.", "**Aucun stéréotype** lié au sexe, à l'âge ou à la situation de l'enfant ou de ses parents : on soutient son identité et son individualité."]}$kk$),
  (2,'comparaison',$kk${"intro": "Pour accueillir chaque enfant tel qu'il est.", "plutot": ["Respecter l'enfant dans sa singularité.", "Observer comment il s'appuie sur les adultes avant d'adapter mon accompagnement.", "Le valoriser pour ses qualités personnelles.", "Accueillir sa famille avec plaisir, respect et confiance."], "eviter": ["Attendre le même comportement de tous les enfants.", "Le catégoriser selon son sexe ou son âge.", "Transmettre des stéréotypes de comportement.", "Juger sa famille ou sa situation."]}$kk$),
  (3,'reflexion',$kk${"question": "Pensez à un enfant du site. Qu'est-ce qui le rend unique, et en quoi votre accompagnement s'adapte-t-il à lui ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche à regarder l'enfant tel qu'il est.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer cette semaine", "titre": "Trois regards sur un enfant", "etapes": [{"titre": "Ce qui le rend unique.", "texte": "Je décris ce qu'il aime, sa façon de s'appuyer sur les adultes, son rythme."}, {"titre": "Ce dont il a besoin.", "texte": "Plus de présence, plus de liberté, plus de temps : je me demande ce que je peux ajuster."}, {"titre": "Ce que j'ajuste.", "texte": "Un geste précis, que je teste toute la semaine."}], "note": "Choisissez un seul de ces gestes et testez-le toute la semaine."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 7 % 1/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 19.1b

-- ---------------------------------------------------------------------------
-- 19.2a Trame de la séquence 2/3 (Analyse d'une situation vécue). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Face à une différence, on regarde ce que l'on peut ajuster, pas ce qui ne va pas chez l'enfant ou sa famille.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable d'analyser une situation où un enfant ou une famille sort de nos habitudes, en décrivant sans étiqueter et en repérant ce qu'il peut ajuster.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Inclusion et égalité des chances"}, "duree_min": 45, "materiel": ["Paperboard", "Fiche de trace"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Retour sur la semaine : chacun dit en une phrase ce qu'il a essayé de son engagement « Cette semaine, je… », sans l'évaluer.", "Demander qui apporte la situation à analyser."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Face à une différence, on ajuste notre accompagnement : on ne catégorise pas.", "idees": ["Les propositions de jeu doivent être adaptées à tous les enfants, quel que soit leur développement, et organisées pour favoriser les interactions positives entre eux, par l'imitation et la création de jeux.", "On accompagne les familles sans les juger : on soutient leurs choix éducatifs, même quand ils ne correspondent pas à nos valeurs, sauf s'ils relèvent des violences faites aux enfants. Dans ce cas, on en parle en équipe éducative et on signale à qui de droit.", "Une étiquette enferme l'enfant dans une vision de lui-même et renforce son comportement. On décrit ce que l'on observe et on en parle en équipe."], "support": "Projet pédagogique Koalakids, « Respecter et accompagner chaque enfant avec confiance et enthousiasme dans l'expression de son plein potentiel d'être humain »."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site", "consigne": "Choisir une situation vécue cette semaine où un enfant ou une famille sortait de nos habitudes, sans les nommer. On analyse la pratique, pas la personne.", "questions": ["Qu'ai-je observé, sans étiquette ?", "Qu'est-ce qui rend cet enfant ou cette famille unique ?", "Qu'est-ce que je peux ajuster (le jeu, l'accueil, mes mots) ?", "Qu'est-ce que j'ai besoin de partager en équipe ?"], "consignes": ["Dans la trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Un engagement concret par personne, à tester pendant la semaine et à raconter à la séance 3.", "amorce": "Cette semaine, je…", "consignes": ["Exemple : décrire ce que j'observe d'un enfant plutôt que dire comment il est.", "Exemple : ajuster une proposition de jeu pour qu'elle convienne à un enfant qui joue autrement.", "Exemple : parler en équipe d'une situation qui m'interroge."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Annoncer la séance 3/3 : retour d'expérience sur la pratique testée, avec un focus sur l'accueil de chaque famille."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 7 % 2/3 %';
-- FIN 19.2a

-- ---------------------------------------------------------------------------
-- 19.2b Blocs de la séquence 2/3. Attendu : 5 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Ajuster, pas catégoriser", "paragraphes": ["Quand un enfant ou une famille sort de nos habitudes, la tentation est de chercher ce qui ne va pas chez eux. Cette séance propose l'inverse : **décrire ce que l'on observe** et chercher ce que l'on peut ajuster.", "On analyse la pratique, jamais la personne : ni l'enfant, ni sa famille, ni le collègue."]}$kk$),
  (1,'scenes',$kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Elle ne joue qu'à côté des autres", "texte": "Léa reste à côté des autres enfants sans entrer dans leurs jeux. Une collègue dit : « Elle est asociale. »", "analyse": "une étiquette enferme l'enfant dans une vision d'elle-même. Les tout-petits font souvent d'abord des offrandes d'objets, acceptent la présence des autres, les imitent, puis construisent des jeux ensemble. On décrit ce que Léa fait, et on propose des objets identiques en nombre suffisant pour favoriser l'imitation."}, {"lettre": "B", "titre": "« Un grand garçon, ça ne pleure pas »", "texte": "Un garçon pleure et on lui dit : « Un grand garçon, ça ne pleure pas. » À une fille qui veut un camion : « Les camions, c'est pour les garçons. »", "analyse": "ce sont des stéréotypes de comportement liés au sexe de l'enfant. On le valorise pour ses qualités personnelles, et son émotion est légitime : on la nomme et on le console."}, {"lettre": "C", "titre": "Des parents qui font autrement", "texte": "La mère de Noé demande qu'on ne lui donne pas de sucette. L'équipe trouve que cela l'aide à se calmer et soupire.", "analyse": "on soutient les choix éducatifs des parents sans les juger, même quand ils ne correspondent pas à nos valeurs. On inscrit leur demande dans le cahier d'équipe pour que chacun la connaisse."}]}$kk$),
  (2,'comparaison',$kk${"intro": "Face à un enfant ou à une famille qui sort de nos habitudes.", "plutot": ["Décrire ce que j'observe plutôt que catégoriser.", "Adapter les propositions de jeu à chaque enfant.", "Soutenir les choix éducatifs des parents sans les juger.", "En parler en équipe quand une situation m'interroge."], "eviter": ["Mettre une étiquette à un enfant ou à une famille.", "Transmettre des stéréotypes liés au sexe ou à l'âge.", "Attendre le même comportement de tous les enfants.", "Juger les choix des parents."]}$kk$),
  (3,'reflexion',$kk${"question": "Y a-t-il une phrase que l'on dit souvent sur le site à propos des enfants (garçons, filles, petits, grands) et qui les enferme dans un rôle ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (4,'essayer',$kk${"label": "À essayer pendant l'analyse", "titre": "Trois questions devant une différence", "etapes": [{"titre": "Qu'est-ce que j'observe ?", "texte": "Les faits, sans étiquette."}, {"titre": "Qu'est-ce qui le rend unique ?", "texte": "Ce qu'il aime, sa façon d'être en relation, son rythme."}, {"titre": "Qu'est-ce que j'ajuste ?", "texte": "Le jeu, l'accueil ou mes mots."}], "note": "On analyse la pratique, jamais la personne."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 7 % 2/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 19.2b

-- ---------------------------------------------------------------------------
-- 19.3a Trame de la séquence 3/3 (Test d'une pratique et retour d'expérience). Attendu : 1 ligne modifiée.
-- ---------------------------------------------------------------------------
update public.module
set accroche = $kk$Chaque famille est accueillie individuellement, avec plaisir, respect et confiance, et en dehors de tout protocole.$kk$,
    trame = coalesce(trame, '{}'::jsonb) || $kk${"objectif": "À la fin, chacun est capable de dire ce qu'a changé la pratique testée dans l'accueil d'un enfant ou d'une famille, et l'équipe a choisi une pratique commune pour accueillir chacun sans condition.", "public": "Toute l'équipe du site", "animateur": "Coordinatrice pédagogique ou référente du site", "socle": {"bloc": 1, "attendu": "Inclusion et égalité des chances"}, "duree_min": 45, "materiel": ["Fiche de trace", "Engagements de la séance 2", "Paperboard"], "deroule": [{"de": 0, "a": 5, "nom": "Ouverture", "consignes": ["Rappeler l'objectif de la séance.", "Chacun relit son engagement de la séance 2 (« Cette semaine, je… »).", "Rappeler la règle : on raconte ce qu'on a fait, on ne se juge pas."]}, {"de": 5, "a": 15, "nom": "Apport", "message": "Un accueil sans condition se joue dès la première rencontre et se poursuit au quotidien.", "idees": ["Chaque famille est accueillie individuellement, en dehors de tout protocole, avec plaisir, respect, confiance et attention. Cet accueil exclut toute forme de discrimination.", "Les parents sont toujours les bienvenus et peuvent circuler librement à la crèche. La crèche favorise aussi l'inclusion des familles confrontées à la pauvreté ou à la précarité, et de celles qui présentent un handicap ou une pathologie chronique.", "On partage ce que l'on observe avec les parents, et on inscrit leurs demandes spécifiques dans le cahier d'équipe pour qu'elles soient connues de tous."], "support": "Projet pédagogique Koalakids, partie sur l'accueil des familles."}, {"de": 15, "a": 30, "nom": "Analyse d'une situation vécue sur le site (retour d'expérience)", "consigne": "Chacun raconte en une minute la pratique qu'il a testée. On cherche ce qui s'est passé, pas qui a bien ou mal fait.", "questions": ["Qu'ai-je testé, et dans quelle situation ?", "Qu'est-ce que cela a changé pour l'enfant ou la famille, même un peu ?", "Qu'est-ce qui a été difficile ?", "Que gardons-nous en équipe ? Que changeons-nous ?"]}, {"de": 30, "a": 40, "nom": "Mise en pratique", "consigne": "Choisir ensemble une pratique commune à tenir pendant deux semaines, puis un engagement par personne.", "amorce": "Cette semaine, je…", "consignes": ["Pratique commune : une phrase que chacun peut décrire de la même façon.", "Chacun s'engage sur un geste précis, noté sur la fiche de trace."]}, {"de": 40, "a": 45, "nom": "Clôture", "consignes": ["Tour de table : un mot sur ce que je retiens.", "Remplir la trace écrite (3 à 5 lignes), sans nom d'enfant.", "Tour de table : ce que je retiens du module 7. Annoncer le prochain module du programme et la date de la première séance."]}], "regles": ["Un message par séance.", "Situations réelles du site.", "Bienveillance : on analyse des pratiques, pas des personnes.", "Toujours finir par un engagement."]}$kk$::jsonb
where titre like 'Module 7 % 3/3 %';
-- FIN 19.3a

-- ---------------------------------------------------------------------------
-- 19.3b Blocs de la séquence 3/3. Attendu : 4 lignes (0 si déjà ajoutés).
-- ---------------------------------------------------------------------------
insert into public.bloc(module_id, type, contenu, ordre)
select m.id, v.type, v.contenu::jsonb, v.ordre
from public.module m
cross join (values
  (0,'texte',$kk${"titre": "Accueillir chacun, individuellement", "paragraphes": ["Chaque famille est unique. Elle est accueillie **individuellement, en dehors de tout protocole**, avec plaisir, respect, confiance et attention. Cet accueil exclut toute forme de discrimination.", "Cette dernière séance sert à regarder ensemble ce que vous avez testé, et à choisir **une pratique commune** pour que chacun se sente bienvenu."]}$kk$),
  (1,'retenir',$kk${"titre": "À retenir", "points": ["**Un accueil individuel :** chaque famille est accueillie avec plaisir, respect, confiance et attention.", "**Les parents sont toujours les bienvenus** et circulent librement. La crèche favorise l'inclusion des familles en précarité et de celles qui présentent un handicap ou une pathologie chronique.", "**Partager et noter :** les observations avec les parents, leurs demandes spécifiques dans le cahier d'équipe."]}$kk$),
  (2,'reflexion',$kk${"question": "Qu'est-ce qui, dans l'accueil d'une famille, vous paraît le plus difficile à faire de façon individuelle ? Qu'est-ce qui vous aiderait ?", "sous_titre": "Il n'y a pas de bonne réponse : on cherche ce qui rendrait l'accueil plus simple.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$),
  (3,'essayer',$kk${"label": "À essayer après la séance", "titre": "Une pratique commune", "etapes": [{"titre": "La choisir ensemble.", "texte": "Un geste simple d'accueil, que chacun fait de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$)
) as v(ordre, type, contenu)
where m.titre like 'Module 7 % 3/3 %'
  and not exists (select 1 from public.bloc b where b.module_id = m.id);
-- FIN 19.3b

-- ---------------------------------------------------------------------------
-- 19c Contrôle (lecture seule). Attendu : 3 séquences, blocs 5 / 5 / 4.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame->>'objectif') is not null as objectif_ok,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs
from public.module m where m.titre like 'Module 7 %/3 %' order by m.ordre;
-- FIN 19c
